import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';


export type ComponentNameProps = Record<string, any>;

// Helper pure component for 3D faces
const Face: React.FC<{ style?: React.CSSProperties; children?: React.ReactNode }> = ({ style, children }) => (
  <div
    style={{
      position: "absolute",
      backfaceVisibility: "hidden",
      ...style,
    }}
  >
    {children}
  </div>
);

const Panel: React.FC<{ s: number; color: string }> = ({ s, color }) => (
  <div
    style={{
      flex: 1,
      backgroundColor: color,
      border: `${2 * s}px solid rgba(0,0,0,0.6)`,
      boxShadow: `
        inset 0px 0px ${15 * s}px rgba(0,0,0,0.5),
        inset ${2 * s}px ${2 * s}px ${6 * s}px rgba(255,255,255,0.1),
        ${2 * s}px ${2 * s}px ${6 * s}px rgba(255,255,255,0.05)
      `,
      boxSizing: "border-box",
    }}
  >
    <div
      style={{
        width: "100%",
        height: "100%",
        border: `${8 * s}px solid rgba(0,0,0,0.15)`,
        borderTopColor: "rgba(0,0,0,0.3)",
        borderLeftColor: "rgba(0,0,0,0.3)",
        borderBottomColor: "rgba(255,255,255,0.05)",
        borderRightColor: "rgba(255,255,255,0.05)",
        boxSizing: "border-box",
      }}
    />
  </div>
);

const Handle: React.FC<{ s: number; isLeft: boolean; color: string; zOffset: number }> = ({ s, isLeft, color, zOffset }) => {
  const horizontalPos = isLeft ? { right: 25 * s } : { left: 25 * s };
  
  return (
    <div
      style={{
        position: "absolute",
        ...horizontalPos,
        top: "52%",
        transform: `translateY(-50%) translateZ(${zOffset}px)`,
        width: 32 * s,
        height: 130 * s,
        backgroundColor: color,
        borderRadius: 4 * s,
        boxShadow: `inset 0 0 ${4 * s}px rgba(0,0,0,0.4), 0 ${4 * s}px ${10 * s}px rgba(0,0,0,0.6)`,
        transformStyle: "preserve-3d",
      }}
    >
      <div
        style={{
          position: "absolute",
          top: "50%",
          [isLeft ? "right" : "left"]: 12 * s,
          width: 75 * s,
          height: 16 * s,
          backgroundColor: color,
          borderRadius: 3 * s,
          transform: `translateY(-50%) translateZ(${6 * s}px)`,
          boxShadow: `inset 0 ${2 * s}px ${4 * s}px rgba(255,255,255,0.3), inset 0 -${2 * s}px ${4 * s}px rgba(0,0,0,0.3), 0 ${4 * s}px ${8 * s}px rgba(0,0,0,0.5)`,
        }}
      />
    </div>
  );
};

const Door: React.FC<{
  s: number;
  width: number;
  height: number;
  thickness: number;
  rotation: number;
  isLeft: boolean;
  color: string;
  handleColor: string;
}> = ({ s, width, height, thickness, rotation, isLeft, color, handleColor }) => {
  const origin = isLeft ? "left center" : "right center";
  const leftPos = isLeft ? 0 : width;

  const edgeColor = "rgba(0,0,0,0.3)"; // Overlay to darken edges

  const panelLayout = (
    <div
      style={{
        width: "100%",
        height: "100%",
        padding: `${45 * s}px`,
        display: "flex",
        flexDirection: "column",
        gap: `${45 * s}px`,
        boxSizing: "border-box",
      }}
    >
      <div style={{ flex: 1.3, display: "flex", flexDirection: "column" }}>
        <Panel s={s} color={color} />
      </div>
      <div style={{ flex: 1, display: "flex", flexDirection: "column" }}>
        <Panel s={s} color={color} />
      </div>
    </div>
  );

  return (
    <div
      style={{
        position: "absolute",
        left: leftPos,
        width,
        height,
        transformOrigin: origin,
        transform: `rotateY(${rotation}deg)`,
        transformStyle: "preserve-3d",
        transition: "none",
      }}
    >
      {/* Front Face */}
      <Face
        style={{
          width,
          height,
          backgroundColor: color,
          transform: `translateZ(${thickness / 2}px)`,
          border: `${2 * s}px solid rgba(0,0,0,0.3)`,
          boxSizing: "border-box",
        }}
      >
        {panelLayout}
        <Handle s={s} isLeft={isLeft} color={handleColor} zOffset={6 * s} />
      </Face>

      {/* Back Face */}
      <Face
        style={{
          width,
          height,
          backgroundColor: color,
          transform: `rotateY(180deg) translateZ(${thickness / 2}px)`,
          border: `${2 * s}px solid rgba(0,0,0,0.3)`,
          boxSizing: "border-box",
        }}
      >
        {panelLayout}
      </Face>

      {/* Right Edge */}
      <Face
        style={{
          width: thickness,
          height,
          left: width - thickness / 2,
          transform: "rotateY(90deg)",
          backgroundColor: color,
        }}
      >
        <div style={{ width: "100%", height: "100%", backgroundColor: edgeColor }} />
      </Face>

      {/* Left Edge */}
      <Face
        style={{
          width: thickness,
          height,
          left: -thickness / 2,
          transform: "rotateY(-90deg)",
          backgroundColor: color,
        }}
      >
        <div style={{ width: "100%", height: "100%", backgroundColor: edgeColor }} />
      </Face>

      {/* Top Edge */}
      <Face
        style={{
          width,
          height: thickness,
          top: -thickness / 2,
          transform: "rotateX(90deg)",
          backgroundColor: color,
        }}
      >
        <div style={{ width: "100%", height: "100%", backgroundColor: edgeColor }} />
      </Face>
      
      {/* Bottom Edge */}
      <Face
        style={{
          width,
          height: thickness,
          bottom: -thickness / 2,
          transform: "rotateX(-90deg)",
          backgroundColor: color,
        }}
      >
        <div style={{ width: "100%", height: "100%", backgroundColor: edgeColor }} />
      </Face>
    </div>
  );
};

const DoubleDoorsOpening: React.FC<ComponentNameProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  doorColor = "#374756",
  frameColor = "#1A2530",
  handleColor = "#D4AF37",
  openAngle = 105,
  startDelayFrames = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Door Dimensions
  const W = 520 * s; // Width of a single door
  const H = 880 * s; // Height of the doors
  const D = 32 * s; // Thickness of the doors
  const FrameT = 70 * s; // Thickness of the door frame

  // Animation Math
  const openProgress = spring({
    frame: Math.max(0, frame - startDelayFrames),
    fps,
    config: {
      damping: 14,
      stiffness: 30,
      mass: 1.5,
    },
  });

  // Swing doors away from the viewer
  const leftRotation = interpolate(openProgress, [0, 1], [0, -openAngle]);
  const rightRotation = interpolate(openProgress, [0, 1], [0, openAngle]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          perspective: `${2200 * s}px`,
        }}
      >
        {/* Master Scene Container */}
        <div
          style={{
            width: 2 * W,
            height: H,
            position: "relative",
            transformStyle: "preserve-3d",
          }}
        >
          {/* Static Door Frame */}
          {/* Header */}
          <div
            style={{
              position: "absolute",
              left: -FrameT,
              top: -FrameT,
              width: 2 * W + 2 * FrameT,
              height: FrameT,
              backgroundColor: frameColor,
              boxShadow: `inset 0 -${10 * s}px ${20 * s}px rgba(0,0,0,0.5)`,
            }}
          />
          {/* Left Jamb */}
          <div
            style={{
              position: "absolute",
              left: -FrameT,
              top: 0,
              width: FrameT,
              height: H,
              backgroundColor: frameColor,
              boxShadow: `inset -${10 * s}px 0 ${20 * s}px rgba(0,0,0,0.5)`,
            }}
          />
          {/* Right Jamb */}
          <div
            style={{
              position: "absolute",
              right: -FrameT,
              top: 0,
              width: FrameT,
              height: H,
              backgroundColor: frameColor,
              boxShadow: `inset ${10 * s}px 0 ${20 * s}px rgba(0,0,0,0.5)`,
            }}
          />
          {/* Bottom Threshold (optional, for grounding) */}
          <div
            style={{
              position: "absolute",
              left: -FrameT,
              bottom: -FrameT * 0.4,
              width: 2 * W + 2 * FrameT,
              height: FrameT * 0.4,
              backgroundColor: frameColor,
              boxShadow: `inset 0 ${5 * s}px ${10 * s}px rgba(0,0,0,0.6)`,
            }}
          />

          {/* Left Door */}
          <Door
            s={s}
            width={W}
            height={H}
            thickness={D}
            rotation={leftRotation}
            isLeft={true}
            color={doorColor}
            handleColor={handleColor}
          />

          {/* Right Door */}
          <Door
            s={s}
            width={W}
            height={H}
            thickness={D}
            rotation={rightRotation}
            isLeft={false}
            color={doorColor}
            handleColor={handleColor}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DoubleDoorsOpening;